import React, { useState, useEffect } from 'react';
import { AuthProvider } from './context/AuthContext';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import Catalog from './pages/Catalog';
import ProductPage from './pages/ProductPage';
import Profile from './pages/Profile';
import Auth from './pages/Auth';
import Contacts from './pages/Contacts';
import About from './pages/About';

function App() {
  const [currentPage, setCurrentPage] = useState('home');
  const [pageParams, setPageParams] = useState({});

  // ✅ Улучшенная обработка хэша в URL
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '');
      console.log('Hash changed to:', hash);

      if (hash) {
        // Обрабатываем профиль с табами
        if (hash.startsWith('profile')) {
          setCurrentPage('profile');
          // Табы профиля обрабатываются внутри компонента Profile
        } 
        // Обрабатываем обычные страницы
        else if (['catalog', 'product', 'auth', 'contacts', 'about'].includes(hash.split('?')[0])) {
          const [page, param] = hash.split('/');
          setCurrentPage(page);
          setPageParams({ id: param });
        }
        // Обрабатываем главную страницу
        else if (hash === 'home') {
          setCurrentPage('home');
        }
        // Если хэш не распознан, показываем главную
        else {
          setCurrentPage('home');
        }
      } else {
        setCurrentPage('home');
      }
    };

    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();

    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  // ✅ Функция навигации
  const navigate = (page, params = {}) => {
    console.log('Navigating to:', page, params);
    setCurrentPage(page);
    setPageParams(params);
    window.location.hash = page + (params.id ? `/${params.id}` : '');
  };

  // ✅ Рендер текущей страницы
  const renderPage = () => {
    console.log('Rendering page:', currentPage);

    switch (currentPage) {
      case 'catalog':
        return <Catalog onNavigate={navigate} />;
      case 'product':
        return <ProductPage onNavigate={navigate} />;
      case 'profile':
        return <Profile onNavigate={navigate} />;
      case 'auth':
        return <Auth onNavigate={navigate} />;
      case 'contacts':
        return <Contacts onNavigate={navigate} />;
      case 'about':
        return <About onNavigate={navigate} />;
      default:
        return <Home onNavigate={navigate} />;
    }
  };

  return (
    <AuthProvider>
      <div className="min-h-screen bg-white">
        <Navbar onNavigate={navigate} />
        {renderPage()}
        <Footer />
      </div>
    </AuthProvider>
  );
}

export default App;
